edits.find:
.profile-info .profile-avatar img {
  width: 40px;
  height: 40px;
  border-radius: 999px;
  object-fit: cover;
}

edits.replace:
.profile-info .profile-avatar img {
  width: 40px;
  height: 40px;
  border-radius: 999px;
  object-fit: cover;
}

/* Initial fallback (no photo): pin the same 40px circle as the photo. The
   generic 100% rule in ProfileAvatar.css has equal specificity and loads later,
   so it stretched this into a pill across the sidebar row. One more class wins. */
.profile-info .profile-avatar:has(.avatar-fallback) {
  width: 40px;
  height: 40px;
}

.profile_heading .bio {
  padding: 16px;
  color: rgba(255,255,255,0.7);
}

/* Initial fallback (no photo): the same 148px ring as the photo. Without a size
   it was 100% of an unsized box and collapsed to a sliver. */
.profile_heading .avatar .profile-avatar:has(.avatar-fallback) {
  width: 148px;
  height: 148px;
}

.profile_heading .avatar .avatar-fallback {
  border: solid 8px var(--fg);
  font-size: 64px;
}
